// FLDesignTokens — Direction H ("the hybrid") palettes.
//
// Source of truth: the direction-h round's own tooling —
// `docs/design-round/direction-h/DIRECTION.md` and its
// `contrast-table.md`, generated by that round's `tools/contrast.mjs`.
// Every hex below except the two kitchen-pill fills is that tool's token
// table, verbatim per mode. H's modes: light (linen/walnut/terracotta),
// dark (P's Twilight Warmth), cook (Twilight hob, ember accent).
//
// H keeps F's ten-role structure but recasts the chromatic seat: there is
// exactly ONE accent (terracotta), so `yolk`/`yolkSoft`/`yolkInk` map to
// `accent`/`accentSoft`/`accentInk` in the base-palette bridge.

/// A mode inside a visual direction. F's `ColorScheme` (paper/hob/dark)
/// stays untouched; directions carry their own mode axis.
public enum DirectionMode: String, Sendable, CaseIterable {
    case light
    case dark
    case cook
}

/// One resolved Direction H palette (one mode).
public struct HPalette: Sendable, Equatable {

    /// Page background. Light: warm linen #F5F0E8.
    public let bg: ColorToken
    /// Row/card ground. Light: surface white #FEFCF8 — H keeps surface-white
    /// rows where long lists run, because linen flattens hairlines.
    public let surface: ColorToken
    /// Walnut ink — text, primary buttons, filled states.
    public let ink: ColorToken
    /// Secondary text (warm grey, F's three-step neutrals).
    public let ink2: ColorToken
    /// Tertiary text; never body-size.
    public let ink3: ColorToken
    /// Hairlines.
    public let rule: ColorToken
    /// Hollow states, dashed/unconfirmed borders.
    public let rule2: ColorToken
    /// The one accent: terracotta. Markers and digits only — never small text.
    public let accent: ColorToken
    /// Accent as a soft fill behind text.
    public let accentSoft: ColorToken
    /// Accent-toned TEXT for links and small text on plain surfaces —
    /// terracotta on linen is 3.65:1 (marker-legal, not text-legal), so
    /// accent text always rides accentInk.
    public let accentInk: ColorToken
    /// Errors only.
    public let error: ColorToken
    /// Primary button fill (light: walnut ink; dark/cook: cream).
    public let buttonFill: ColorToken
    /// Label on the primary button fill.
    public let buttonLabel: ColorToken
    /// Warm photo placeholder ground (hatch drawn on it).
    public let photoPlaceholder: ColorToken
    /// Kitchen pill, idle stock: warm surface fill, linen-tinted.
    /// Package-defined (mandated by the design-system task, not in the
    /// direction doc): contrast-tested as a fill (ink text on it ≥4.5) and
    /// as a marker (≥1.15 against bg so the pill shape reads; documented
    /// package floor — WCAG has no fill-vs-ground floor).
    public let pillIdle: ColorToken
    /// Kitchen pill, item gone: deeper linen-tinted fill, reads more
    /// recessed than pillIdle (lightness ordering is asserted).
    public let pillGone: ColorToken

    public init(
        bg: ColorToken, surface: ColorToken, ink: ColorToken, ink2: ColorToken,
        ink3: ColorToken, rule: ColorToken, rule2: ColorToken, accent: ColorToken,
        accentSoft: ColorToken, accentInk: ColorToken, error: ColorToken,
        buttonFill: ColorToken, buttonLabel: ColorToken, photoPlaceholder: ColorToken,
        pillIdle: ColorToken, pillGone: ColorToken
    ) {
        self.bg = bg
        self.surface = surface
        self.ink = ink
        self.ink2 = ink2
        self.ink3 = ink3
        self.rule = rule
        self.rule2 = rule2
        self.accent = accent
        self.accentSoft = accentSoft
        self.accentInk = accentInk
        self.error = error
        self.buttonFill = buttonFill
        self.buttonLabel = buttonLabel
        self.photoPlaceholder = photoPlaceholder
        self.pillIdle = pillIdle
        self.pillGone = pillGone
    }

    /// Bridge to the closed ten-role palette FLDesignSystem already renders
    /// with: the accent takes the yolk seat. This is what lets a direction
    /// swap in without touching a single component.
    public var basePalette: Palette {
        Palette(
            bg: bg, ink: ink, ink2: ink2, ink3: ink3,
            rule: rule, rule2: rule2, yolk: accent, yolkSoft: accentSoft,
            yolkInk: accentInk, error: error
        )
    }
}

/// Direction H's three mode palettes.
