        surface: ColorToken(hex: 0x24211C),
        ink: ColorToken(hex: 0xF2EDE3),
        ink2: ColorToken(hex: 0xBDB09E),
        ink3: ColorToken(hex: 0x8B7F6C),
        rule: ColorToken(hex: 0x2B2620),
        rule2: ColorToken(hex: 0x716655),
        accent: ColorToken(hex: 0xD98059),
        accentSoft: ColorToken(hex: 0x342218),
        accentInk: ColorToken(hex: 0xEFA47D),
        error: ColorToken(hex: 0xFF6B57),
        buttonFill: ColorToken(hex: 0xF2EDE3),
        buttonLabel: ColorToken(hex: 0x1E1C17),
        photoPlaceholder: ColorToken(hex: 0x1E1B16),
        pillIdle: ColorToken(hex: 0x39332B),
        pillGone: ColorToken(hex: 0x332E26)
