    public static let cook = HPalette(
        bg: ColorToken(hex: 0x1E1C17),
        surface: ColorToken(hex: 0x28251E),
        ink: ColorToken(hex: 0xF2EDE3),
        ink2: ColorToken(hex: 0xB5A995),
        ink3: ColorToken(hex: 0x7E7461),
        rule: ColorToken(hex: 0x312C24),
        rule2: ColorToken(hex: 0x7E7461),
        accent: ColorToken(hex: 0xE08B62),
        accentSoft: ColorToken(hex: 0x35241A),
        accentInk: ColorToken(hex: 0xF0A97F),
        error: ColorToken(hex: 0xFF6B57),
        buttonFill: ColorToken(hex: 0xF2EDE3),
        buttonLabel: ColorToken(hex: 0x1E1C17),
        photoPlaceholder: ColorToken(hex: 0x262219),
        pillIdle: ColorToken(hex: 0x39332B),
        pillGone: ColorToken(hex: 0x332E26)
    )

    /// Resolves one mode's palette.
    public static func palette(_ mode: DirectionMode) -> HPalette {
        switch mode {
        case .light: return light
        case .dark: return dark
        case .cook: return cook
        }
    }
}
